async function pageFunction(context) {
    const { log, request, jQuery: $ } = context;
    const results = [];

    // Extract all listing items
    const items = $('.article-item-container');

    items.each((i, item) => {
      const $item = $(item);

      const title = $item.find('.h3').text().trim() || 
                    $item.find('.article-title').text().trim();

      const priceText = $item.find('[data-currency"="EUR"]').text().trim() || 
                        $item.find('.price').text().trim();
      const price = priceText ? parseInt(priceText.replace(/[^\d]/g, '')) : null;

      const condition = $item.find('.condition-label').text().trim() || 
                        $item.find('.article-condition').text().trim() || 'unspecified';

      const conditionLower = condition.toLowerCase();
      const hasBox = conditionLower.includes('box') || conditionLower.includes('komplett');
      const hasPapers = conditionLower.includes('papers') || conditionLower.includes('ausweis');

      const sellerName = $item.find('.professional-name, .dealer-name').text().trim() || 'private';
      const sellerRating = $item.find('.rating-stars').length * 20 || null;

      const link = $item.find('a[href*=

]').attr('href');

      if (title && price) {
        results.push({
          title,
          price_egp: price,
          condition: conditionLower.includes('new') ? 'unworn' :
                    conditionLower.includes('excellent') ? 'excellent' :
                    conditionLower.includes('very good') ? 'very_good' :
                    conditionLower.includes('good') ? 'good' : 'fair',
          has_box: hasBox,
          has_papers: hasPapers,
          seller_name: sellerName,
          seller_rating: sellerRating,
          url: link ? 'https://www.chrono24.com' + link : null,
          source: 'chrono24',
          scraped_at: new Date().toISOString()
        });
      }
    });

    return { results, pageTitle: document.title };
  }
